}

coding.referenceSolution:
function hitSlop(size, platform) {
  const min = platform === "android" ? 48 : 44;
  const pad = Math.max(0, Math.ceil((min - size) / 2));
  return { top: pad, bottom: pad, left: pad, right: pad };
}

