coding.referenceSolution:
function parseDeepLink(url) {
  let rest = url.replace(/^[a-z][a-z0-9+.-]*:\/\//i, "");
  if (/^https?:/i.test(url)) rest = rest.replace(/^[^/?#]*/, "");
  const [pathPart, qs = ""] = rest.split("?");
  const path = pathPart.split("/").filter(Boolean);
  const query = {};
  for (const pair of qs.split("&").filter(Boolean)) {
    const [k, v = ""] = pair.split("=");
    query[decodeURIComponent(k)] = decodeURIComponent(v.replace(/\+/g, " "));
  }
  return { path, query };
}

