coding.referenceSolution:
function sections(contacts) {
  const groups = {};
  for (const name of contacts) {
    const first = name[0] ? name[0].toUpperCase() : "#";
    const k = first >= "A" && first <= "Z" ? first : "#";
    (groups[k] = groups[k] || []).push(name);
  }
  const keys = Object.keys(groups).filter((k) => k !== "#").sort();
  if (groups["#"]) keys.push("#");
  return keys.map((title) => ({
    title,
    data: groups[title].sort((a, b) => a.toLowerCase().localeCompare(b.toLowerCase())),
  }));
}

