}

coding.referenceSolution:
function visibleRange(count, itemHeight, offset, viewport) {
  if (count === 0) return null;
  const first = Math.min(count - 1, Math.max(0, Math.floor(offset / itemHeight)));
  const last = Math.min(count - 1, Math.max(0, Math.ceil((offset + viewport) / itemHeight) - 1));
  return [first, last];
}

