function matchLink(config, path) {
  for (const [screen, pattern] of Object.entries(config)) {
    if (pattern === path) return { screen, params: {} };
  }
  return null;
}

coding.referenceSolution:
function matchLink(config, path) {
  const segs = path.split("/").filter(Boolean);
  for (const [screen, pattern] of Object.entries(config)) {
    const p = pattern.split("/").filter(Boolean);
    if (p.length !== segs.length) continue;
    const params = {};
    let ok = true;
    for (let i = 0; i < p.length; i++) {
      if (p[i].startsWith(":")) params[p[i].slice(1)] = segs[i];
      else if (p[i] !== segs[i]) { ok = false; break; }
    }
    if (ok) return { screen, params };
  }
  return null;
}

