coding.referenceSolution:
function needsUpdate(installed, minimum) {
  const a = installed.split(".").map(Number);
  const b = minimum.split(".").map(Number);
  for (let i = 0; i < Math.max(a.length, b.length); i++) {
    const x = a[i] || 0;
    const y = b[i] || 0;
    if (x !== y) return x < y;
  }
  return false;
}

function enqueue(queue, op) {
  const i = queue.findIndex((q) => q.id === op.id);
  if (i === -1) return [...queue, op];
  const prev = queue[i];
  const out = [...queue];
  if (op.type === "update" && (prev.type === "create" || prev.type === "update")) {
    out[i] = { ...prev, data: { ...prev.data, ...op.data } };
    return out;
  }
  if (op.type === "delete" && prev.type === "create") {
    out.splice(i, 1);
    return out;
  }
  if (op.type === "delete" && prev.type === "update") {
    out[i] = { type: "delete", id: op.id };
    return out;
  }
  return [...queue, op];
}

coding.starterCode:
function afterSync(queue, failedIds, maxAttempts) {
  return { queue: queue.filter((op) => failedIds.includes(op.id)), dead: [] };
}

coding.referenceSolution:
function afterSync(queue, failedIds, maxAttempts) {
  const out = [];
  const dead = [];
  for (const op of queue) {
    if (!failedIds.includes(op.id)) continue;
    const attempts = op.attempts + 1;
    if (attempts >= maxAttempts) dead.push(op.id);
    else out.push({ ...op, attempts });
  }
  return { queue: out, dead };
}

