function resolve(local, server) {
  const byId = {};
  for (const r of [...server, ...local]) byId[r.id] = r;
  return Object.values(byId);
}

coding.referenceSolution:
function resolve(local, server) {
  const byId = {};
  for (const r of local) byId[r.id] = r;
  for (const r of server) {
    const cur = byId[r.id];
    if (!cur || r.updatedAt >= cur.updatedAt) byId[r.id] = r;
  }
  return Object.values(byId)
    .filter((r) => !r.deleted)
    .sort((a, b) => (a.id < b.id ? -1 : a.id > b.id ? 1 : 0));
}

